t.script:

(function () {
    'use strict';

    var forms = document.querySelectorAll('.needs-validation');

    Array.prototype.slice.call(forms).forEach(function (form) {
        form.addEventListener('submit', function (event) {
            if (!form.checkValidity()) {
                event.preventDefault();
                event.stopPropagation();

                var firstInvalid = form.querySelector(':invalid');
                if (firstInvalid) {
                    firstInvalid.scrollIntoView({
                        behavior: 'smooth',
                        block: 'center'
                    });

                    try {
                        firstInvalid.focus({ preventScroll: true });
                    } catch (e) {}
                }

                form.classList.add('was-validated');
                return false;
            }

            var submitButton = form.querySelector('#o_eval_submit_btn');
            if (submitButton) {
                submitButton.disabled = true;
                submitButton.innerHTML = '<i class="fa fa-spinner fa-spin me-2"></i>Enviando...';
            }

            form.classList.add('was-validated');
        }, false);
    });

    var inputs = document.querySelectorAll('.form-check-input, .btn-check, .star-input');

    Array.prototype.slice.call(inputs).forEach(function (input) {
        input.addEventListener('change', function () {
            var questionCard = input.closest('.o_question_card');
            if (questionCard) {
                questionCard.classList.remove('o_question_error');
            }
        });
    });
})();
